import {PERSONAS} from './catalog.js?v=4';
export class CustomerDesk{
 constructor(api){this.api=api;this.opened=false;this.modal=document.createElement('div');this.modal.id='customer-dialog';this.modal.className='modal hidden';this.modal.setAttribute('role','dialog');this.modal.setAttribute('aria-modal','true');this.modal.setAttribute('aria-labelledby','customer-title');document.body.append(this.modal);
  document.getElementById('talk').addEventListener('click',()=>this.open());this.modal.addEventListener('click',e=>{const b=e.target.closest('[data-customer]');if(!b){if(e.target===this.modal)this.close();return;}const action=b.dataset.customer;if(action==='close')this.close();if(action==='hint'){this.modal.querySelector('.diagnosis').classList.remove('hidden');b.disabled=true;b.textContent='已经记下故障啦';}if(action==='return'){const {job}=api.get();job.returnItem();api.save();api.render();this.close();api.next();}});
  document.addEventListener('keydown',e=>{if(!this.opened)return;if(e.key==='Escape'){e.stopImmediatePropagation();e.preventDefault();this.close();}if(e.key==='Tab'){const buttons=[...this.modal.querySelectorAll('button:not(:disabled)')],first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}},true);
 }
 open(){const {job,jobs,cards}=this.api.get(),s=job.spec,p=PERSONAS[s.id]||{},color=p.color||`#${s.palette[0].toString(16).padStart(6,'0')}`,hat=p.hat||`#${s.palette[1].toString(16).padStart(6,'0')}`,done=job.completed;
  this.api.pause(true);this.opened=true;this.modal.classList.remove('hidden');this.modal.innerHTML=`<div class="customer-card"><button class="customer-close" data-customer="close" aria-label="关闭顾客对话">×</button><div class="customer-portrait" style="--coat:${color};--hat:${hat}"><i class="customer-hat"></i><i class="customer-face"><b></b><b></b><em></em></i><i class="customer-coat"></i></div><small class="customer-eyebrow">${done?'THANK YOU, LITTLE REPAIR SHOP':'A LITTLE STORY AT YOUR WORKBENCH'}</small><h2 id="customer-title">${s.owner}</h2><span class="customer-item">收件单 ${s.number} · ${s.name}</span><blockquote>${done?s.thanks||p.thanks||s.finish:s.note}</blockquote>${done?`<div class="thank-you-card"><span>♥</span><div><b>${job.returned?'这份心意，已经收藏好了。':cards.includes(s.id)?'又收到老朋友的感谢卡。':'一张亲手写的感谢卡。'}</b><p>${s.finish}</p></div><small>收藏 ${cards.length} / ${jobs.length}</small></div>`:`<button data-customer="hint" class="ask-customer">问问哪里坏了 ↗</button><p class="diagnosis hidden">${s.diagnosis||p.diagnosis||'按照工作台提示修好故障，再做一次测试。'}</p>`}<button class="primary customer-primary" data-customer="${done&&!job.returned?'return':'close'}">${done&&!job.returned?'收下感谢卡，接下一件 ↗':done?'继续开工':'我来帮你修好它'}</button><p class="customer-small">${done?'修好的不只是旧物，还有一点好心情。':'对话时，维修和计时已暂停。'}</p></div>`;
  this.modal.querySelector('.customer-close').focus();
 }
 close(){if(!this.opened)return;this.opened=false;this.modal.classList.add('hidden');this.api.pause(false);document.getElementById('talk').focus();}
}
